-- 08-player-team-assignments: uploaded workbook snapshot. Run entire file, then Write Changes.
-- Save pending edits and take a backup first. No BEGIN/COMMIT needed in DB Browser.
-- Identical reruns are safe; changed existing records are never overwritten.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_season_8;
CREATE TEMP TABLE afl_season_import_stamp(effective_at TEXT NOT NULL);
CREATE TEMP TABLE afl_season_8_0 AS SELECT id, season_id, player_id, team_id, effective_from, effective_until, source, status FROM player_team_assignments WHERE 0;
CREATE TEMP TABLE afl_season_8_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_season_8_check BEFORE INSERT ON afl_season_8_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import season (05) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_8_0 i LEFT JOIN players p ON p.id=i.player_id WHERE p.id IS NULL OR p.league_id<>'36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Player IDs missing or belong to another league; import reviewed players first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_8_0 i LEFT JOIN teams t ON t.id=i.team_id WHERE i.team_id IS NOT NULL AND (t.id IS NULL OR t.league_id<>'36c6e53f-7be2-5a94-84a8-0df871aae9fd')) THEN RAISE(ROLLBACK,'Team IDs missing or belong to another league.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_8_0 i LEFT JOIN team_seasons ts ON ts.season_id=i.season_id AND ts.team_id=i.team_id WHERE i.team_id IS NOT NULL AND ts.id IS NULL) THEN RAISE(ROLLBACK,'Import team-season details (06) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_8_0 i JOIN player_team_assignments t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.effective_from IS NOT i.effective_from OR t.effective_until IS NOT i.effective_until OR t.source IS NOT i.source OR t.status IS NOT i.status) THEN RAISE(ROLLBACK,'player_team_assignments: existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_8_0 i JOIN player_team_assignments t ON t.season_id=i.season_id AND t.player_id=i.player_id AND t.status='active' AND (t.effective_until IS NULL OR julianday(i.effective_from)<julianday(t.effective_until)) WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'player_team_assignments: natural key belongs to another ID.') END;
END;
DROP TRIGGER afl_season_8_check;
DROP TABLE afl_season_8_guard;
DROP TABLE afl_season_8_0;
DROP TABLE afl_season_import_stamp;
RELEASE SAVEPOINT afl_season_8;
PRAGMA foreign_key_check;
